import{_ as i,o as t,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const P=JSON.parse('{"title":"Pulpito 2.0- A Tour of Pulpito Next-Generation - Vallari Agrawal, IBM","description":"","frontmatter":{"title":"Pulpito 2.0- A Tour of Pulpito Next-Generation - Vallari Agrawal, IBM","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Pulpito","功能更新","用户界面","自动化","管理工具"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Pulpito_2.0_-_A_Tour_of_Pulpito_Next-Generation_-_Vallari_Agrawal_IBM.md","filePath":"posts/2025/Pulpito_2.0_-_A_Tour_of_Pulpito_Next-Generation_-_Vallari_Agrawal_IBM.md","lastUpdated":1780459816000}'),a={name:"posts/2025/Pulpito_2.0_-_A_Tour_of_Pulpito_Next-Generation_-_Vallari_Agrawal_IBM.md"};function n(u,l,e,p,_,s){return t(),o("div",null,[...l[0]||(l[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>: 新版Pulpito 2.0展示及功能更新</p><p><strong>参会人员</strong>: Larry团队</p><p><strong>会议时间</strong>: 不详</p><p><strong>会议内容</strong>:</p><ol><li><p><strong>新版Pulpito 2.0展示</strong>:</p><ul><li>新版Pulpito采用现代工具开发，增加了高级功能。</li><li>用户可以通过当前的Pulpito界面访问新版面板。</li></ul></li><li><p><strong>Run页面定制化</strong>:</p><ul><li>增加了Run页面的过滤菜单，支持按状态、名称、用户名等多字段过滤。</li><li>支持组合过滤，最多可设置五个过滤条件。</li></ul></li><li><p><strong>Job列表表的定制化</strong>:</p><ul><li>支持在Job列表中切换显示或隐藏列。</li><li>新增任务列表和描述，用户可以直接从表格视图中查看任务和描述。</li></ul></li><li><p><strong>全局过滤功能</strong>:</p><ul><li>新增全局过滤功能，支持跨所有字段（隐藏和显示）搜索。</li><li>用户可以结合多个过滤条件进行搜索。</li></ul></li><li><p><strong>Job历史查看</strong>:</p><ul><li>新增“显示历史”按钮，用户可以查看过去25个具有相同描述的任务的历史记录。</li></ul></li><li><p><strong>一键终止Run</strong>:</p><ul><li>支持通过GitHub认证后，用户可以一键终止自己的Run。</li><li>管理员可以终止其他用户的Run。</li></ul></li><li><p><strong>用户权限管理</strong>:</p><ul><li>非管理员用户在终止Run时会收到警告，提示其无管理员权限。</li><li>管理员可以通过GitHub用户名终止其他用户的Run。</li></ul></li><li><p><strong>Lazy Suite命令共享</strong>:</p><ul><li>正在开发将Lazy Suite命令保存到数据库并与其他用户共享的功能。</li><li>用户可以搜索其他用户的预设并运行。</li></ul></li><li><p><strong>未来计划</strong>:</p><ul><li>计划增加Side Rendering功能，减少对VPA的依赖。</li><li>探索将Lazy Jobs容器化的可能性。</li></ul></li></ol><p><strong>决定事项</strong>:</p><ul><li>继续开发和完善新版Pulpito 2.0的功能。</li><li>探索Lazy Jobs的容器化及Side Rendering的实现。</li></ul><p><strong>后续行动计划</strong>:</p><ul><li>完成Lazy Suite命令共享功能的开发。</li><li>确定Lazy Jobs容器化的具体实现方案和时间表。</li></ul><p><strong>会议总结</strong>: Larry团队展示了新版Pulpito 2.0的多个新功能，包括Run页面的过滤、Job列表的定制化、全局过滤、Job历史查看、一键终止Run等。团队还讨论了未来的开发计划，包括Lazy Suite命令共享和Lazy Jobs的容器化。</p>',11)])])}const d=i(a,[["render",n]]);export{P as __pageData,d as default};
